"""Independent synthetic comparisons, not expected outputs regenerated by Rust."""
import importlib.util, unittest
from pathlib import Path
spec=importlib.util.spec_from_file_location('comparison',Path(__file__).resolve().parents[2]/'scripts/compare-southwark-validation.py')
m=importlib.util.module_from_spec(spec);spec.loader.exec_module(m)
class Controls(unittest.TestCase):
    def plant(self):
        ref={'source_sha256':'known','status':'awaiting_human_confirmation','claims':[{'id':'F1','human_review_status':None,'expected_fields':{'contribution.Test.amount.value_gbp':'100','contribution.Test.conditionality.kind':'conditional','housing.claimed_affordable_basis':'habitable_rooms'}}]}
        audit={'agreement':{'provenance':{'sha256':'known'},'housing':{'claimed_affordable_basis':'habitable_rooms','tenures':[]},'contributions':[{'name':'Test','amount':{'value_gbp':'100.00'},'conditionality':{'kind':'conditional'}}]},'verification':[]}
        return ref,audit
    def test_clean_and_each_corruption(self):
        ref,a=self.plant();self.assertEqual(m.compare(ref,a)['agent_labelled']['agree'],3)
        for kind in ['amount','conditionality','basis','omission']:
            ref,a=self.plant()
            if kind=='amount': a['agreement']['contributions'][0]['amount']['value_gbp']='101'
            if kind=='conditionality': a['agreement']['contributions'][0]['conditionality']['kind']='unconditional'
            if kind=='basis': a['agreement']['housing']['claimed_affordable_basis']='units'
            if kind=='omission': a['agreement']['contributions']=[]
            r=m.compare(ref,a);self.assertGreater(r['agent_labelled']['different']+r['agent_labelled']['missing'],0,kind)
    def test_citation_corruption(self):
        ref,a=self.plant();a['agreement']['housing']['total_units_evidence']={'page':14}
        self.assertEqual(m.compare(ref,a,{'locator_checks':{'housing.total_units_evidence.page':[14,45]}})['locator_checks'][0]['outcome'],'agree')
        a['agreement']['housing']['total_units_evidence']['page']=44
        self.assertEqual(m.compare(ref,a,{'locator_checks':{'housing.total_units_evidence.page':[14,45]}})['locator_checks'][0]['outcome'],'different')
    def test_empty_human_denominator_and_invalid_confirmation(self):
        ref,a=self.plant();self.assertIsNone(m.compare(ref,a)['human_confirmed'])
        ref['claims'][0]['human_review_status']='confirmed'
        with self.assertRaises(ValueError): m.compare(ref,a)
    def test_source_mismatch(self):
        ref,a=self.plant();a['agreement']['provenance']['sha256']='wrong'
        with self.assertRaises(ValueError): m.compare(ref,a)
    def test_empty_reference_rejected(self):
        ref,a=self.plant();ref['claims']=[]
        with self.assertRaises(ValueError): m.compare(ref,a)
if __name__=='__main__': unittest.main()
